#!/usr/bin/env node

'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');

const PLUGIN_NAME = 'gossamer';
const PLUGIN_SOURCE = 'npm';
const PLUGIN_KEY = `${PLUGIN_NAME}@${PLUGIN_SOURCE}`;
const VERSION = require('./package.json').version;

const claudeDir = path.join(os.homedir(), '.claude');
const pluginsDir = path.join(claudeDir, 'plugins');
const installPath = path.join(pluginsDir, 'cache', PLUGIN_SOURCE, PLUGIN_NAME, VERSION);
const installedPluginsPath = path.join(pluginsDir, 'installed_plugins.json');
const settingsPath = path.join(claudeDir, 'settings.json');

function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyDir(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

function readJson(filePath, fallback) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch {
    return fallback;
  }
}

function writeJson(filePath, data) {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + '\n', 'utf8');
}

// Copy plugin files into ~/.claude/plugins/cache/
console.log(`Installing ${PLUGIN_KEY} to ${installPath}...`);
fs.mkdirSync(installPath, { recursive: true });

const pkgRoot = __dirname;
copyDir(path.join(pkgRoot, '.claude-plugin'), path.join(installPath, '.claude-plugin'));
